fn prime_num(n: u64) -> bool {
    // We assume n >= 2, but handle small cases for completeness
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    // Exclude even numbers > 2
    if n % 2 == 0 {
        return false;
    }
    // Test odd divisors up to sqrt(n)
    let mut i: u64 = 3;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

